sys_script_client.script:
function onSubmit() {
    var college = g_form.getValue('college');
    var requestedBy = g_form.getValue('requested_by');
    var documents = g_form.getValue('documents');
    var missing = [];

    if (!college) {
        missing.push('College');
    }
    if (!requestedBy) {
        missing.push('Requested By');
    }
    if (!documents) {
        missing.push('Documents');
    }

    if (missing.length > 0) {
        g_form.clearMessages();
        g_form.addErrorMessage('Please fill in all required fields before submitting: ' + missing.join(', '));
        return false;
    }
    return true;
}
